<template>
  <div class="shell">
    <header class="topbar">
      <strong class="brand">🐾 寻猫线索</strong>
      <nav><button v-for="tab in tabs" :key="tab.id" :class="{ active: page === tab.id }" @click="navigate(tab.id)">{{ tab.label }}</button></nav>
      <button class="link" @click="token ? logout() : (authOpen = true)">{{ token ? `${username} · 退出` : '登录 / 注册' }}</button>
    </header>
    <main>
      <section class="hero"><p class="eyebrow">让每一条目击都有机会被看见</p><h1>一起帮猫找到回家的路</h1><p>照片、时间与地点组合检索，为走失猫和目击线索建立联系。候选需要由双方进一步核实。</p><div class="actions"><button class="primary" @click="choose('lost')">我的猫走失了</button><button class="secondary" @click="choose('sighting')">我发现了一只猫</button></div></section>
      <p v-if="notice" class="notice" role="status">{{ notice }}</p>

      <section v-if="page === 'publish'" class="content">
        <div class="heading"><span>发布线索</span><h2>{{ form.type === 'lost' ? '发布走失猫信息' : '发布发现猫信息' }}</h2><p>填写真实的事发信息。品种、毛色不确定时可以留空。</p></div>
        <div class="switch"><button :class="{ selected: form.type === 'lost' }" @click="form.type = 'lost'">我丢了猫</button><button :class="{ selected: form.type === 'sighting' }" @click="form.type = 'sighting'">我发现猫</button></div>
        <form class="panel" @submit.prevent="publish">
          <div class="grid">
            <label>城市 *<input v-model.trim="form.event_city" required maxlength="100" placeholder="例如：上海" /></label>
            <label>区县 *<input v-model.trim="form.event_district" required maxlength="100" placeholder="例如：浦东新区" /></label>
            <label>{{ form.type === 'lost' ? '最后见到时间' : '发现时间' }} *<input v-model="form.event_time" required type="datetime-local" /></label>
            <label>毛色<input v-model.trim="form.desc.coat_color" maxlength="50" placeholder="例如：橘白；不确定可留空" /></label>
            <label>花纹<input v-model.trim="form.desc.pattern" maxlength="50" placeholder="例如：虎斑" /></label>
            <label>品种<input v-model.trim="form.desc.breed" maxlength="100" placeholder="不确定可留空" /></label>
            <label>体型<select v-model="form.desc.size"><option value="">不确定</option><option>小</option><option>中</option><option>大</option></select></label>
          </div>
          <div class="location"><div><strong>事发地点坐标（选填）</strong><p>只有你就在走失或发现地点时，才使用当前定位。</p></div><button type="button" class="secondary small" @click="useLocation">使用当前位置</button><span v-if="form.event_lat !== null">已定位</span></div>
          <label class="upload">猫的照片 * <small>1–5 张 JPG/PNG，建议包含正脸、侧面和全身。</small><input type="file" accept="image/jpeg,image/png" multiple @change="selectFiles" /></label>
          <div v-if="previews.length" class="previews"><div v-for="(src, i) in previews" :key="src"><img :src="src" :alt="`待上传照片 ${i + 1}`" /><button type="button" @click="removeFile(i)">×</button></div></div>
          <p class="tip">公开页面只展示区县和照片；联系通过站内请求进行。</p>
          <button class="primary submit" :disabled="busy">{{ busy ? '正在发布…' : '发布并查找疑似匹配' }}</button>
        </form>
        <section v-if="matchesShown" class="results"><div class="heading"><span>检索结果</span><h2>可能相关的线索</h2><p>图像相似分用于排序，不代表认领概率。当前范围：{{ searchScope === 'all_cities' ? '全部城市' : '同城' }}。</p><button v-if="searchScope !== 'all_cities'" class="secondary small" @click="expandMatches">扩大到全部城市</button></div><div v-if="!matches.length" class="empty">暂时没有候选；新线索出现后可在“我的发布”中再次查看。</div><div v-else class="result-grid"><article v-for="item in matches" :key="item.id" class="result"><img :src="item.image_url" alt="候选猫照片" /><div><small>{{ item.city }} {{ item.district }} · {{ item.event_time }}</small><h3>{{ item.desc.coat_color || '毛色未知' }}的猫</h3><p>{{ item.reasons.join(' · ') }}</p><p>图像相似分 {{ item.score.toFixed(3) }}</p><button class="secondary small" @click="contact(item, matchTargetType)">发送联系请求</button></div></article></div></section>
      </section>

      <section v-else-if="page === 'browse'" class="content"><div class="heading"><span>公开线索</span><h2>浏览走失与发现信息</h2></div><div class="filters"><select v-model="browseType"><option value="lost">走失猫</option><option value="sighting">发现猫</option></select><input v-model.trim="browseCity" placeholder="城市（选填）" @keyup.enter="loadBrowse" /><button class="secondary small" @click="loadBrowse">筛选</button></div><div v-if="!browseItems.length" class="empty">暂无符合条件的线索。</div><div v-else class="result-grid"><article v-for="item in browseItems" :key="item.id" class="result"><img :src="item.images[0]" alt="猫照片" /><div><small>{{ item.type === 'lost' ? '走失' : '发现' }}</small><h3>{{ item.desc.coat_color || '毛色未知' }}的猫</h3><p>{{ item.event_city }} · {{ item.event_district }}</p><p>{{ item.event_time }}</p><button class="secondary small" @click="contact(item, item.type)">联系发布者</button></div></article></div></section>

      <section v-else class="content"><div class="heading"><span>我的线索</span><h2>管理已发布的信息</h2><p>猫已找回或线索失效时请及时关闭。</p></div><div v-if="!token" class="empty">登录后可查看你的发布。</div><div v-else-if="!myItems.length" class="empty">你还没有发布记录。</div><div v-else class="my-list"><article v-for="item in myItems" :key="item.id" class="my-item"><img :src="item.images[0]" alt="猫照片" /><div><strong>{{ item.type === 'lost' ? '走失' : '发现' }} · {{ item.event_city }} {{ item.event_district }}</strong><p>{{ item.event_time }} · {{ item.status }}</p></div><div class="my-actions"><button v-if="item.status === 'active'" class="secondary small" @click="viewMatches(item)">查看匹配</button><button v-if="item.status === 'active'" class="link" @click="closeReport(item)">标记已解决</button></div></article></div><section v-if="token" class="inbox"><h2>联系请求</h2><div v-if="!contactItems.length" class="empty">暂无联系请求。</div><article v-for="item in contactItems" :key="item.id" class="message"><p>{{ item.message }}</p><small>{{ item.reply ? `已回复：${item.reply}` : item.direction === 'sent' ? '等待发布者回复' : '待回复' }}</small><div v-if="item.state === 'pending' && item.direction === 'received'"><input v-model="replies[item.id]" placeholder="回复联系请求" /><button class="secondary small" @click="reply(item)">回复</button></div></article></section></section>
    </main>
    <div v-if="authOpen" class="overlay" @click.self="authOpen = false"><form class="dialog" @submit.prevent="authenticate"><button type="button" class="close" @click="authOpen = false">×</button><span class="eyebrow">寻猫线索</span><h2>{{ registerMode ? '创建账号' : '登录账号' }}</h2><label>用户名<input v-model.trim="auth.username" required minlength="3" autocomplete="username" /></label><label>密码<input v-model="auth.password" type="password" required minlength="8" :autocomplete="registerMode ? 'new-password' : 'current-password'" /></label><button class="primary submit" :disabled="busy">{{ registerMode ? '注册并登录' : '登录' }}</button><button type="button" class="link" @click="registerMode = !registerMode">{{ registerMode ? '已有账号？登录' : '没有账号？注册' }}</button></form></div>
    <div v-if="contactTarget" class="overlay" @click.self="contactTarget = null"><form class="dialog" @submit.prevent="sendContact"><button type="button" class="close" @click="contactTarget = null">×</button><span class="eyebrow">安全联系</span><h2>联系线索发布者</h2><p>请说明核对依据，不要在公开页面留下电话号码。</p><textarea v-model.trim="contactMessage" required minlength="5" maxlength="1000" rows="5" placeholder="例如：我家猫左耳有缺口，可以核对另一张照片吗？"></textarea><button class="primary submit" :disabled="busy">发送站内请求</button></form></div>
  </div>
</template>

<script setup>
import { ref, reactive, onUnmounted } from 'vue'
import axios from 'axios'

const tabs = [{ id: 'publish', label: '发布线索' }, { id: 'browse', label: '浏览信息' }, { id: 'mine', label: '我的发布' }]
const page = ref('publish'), notice = ref(''), busy = ref(false)
const token = ref(localStorage.getItem('cat_token') || ''), username = ref(localStorage.getItem('cat_user') || '')
const authOpen = ref(false), registerMode = ref(false), auth = reactive({ username: '', password: '' })
const form = reactive({ type: 'lost', event_city: '', event_district: '', event_time: '', event_lat: null, event_lng: null, desc: { coat_color: '', pattern: '', size: '', breed: '' } })
const files = ref([]), previews = ref([]), matches = ref([]), matchesShown = ref(false), matchTargetType = ref('sighting'), searchScope = ref('same_city'), activeReport = ref(null)
const browseType = ref('lost'), browseCity = ref(''), browseItems = ref([]), myItems = ref([]), contactItems = ref([])
const contactTarget = ref(null), contactType = ref(''), contactMessage = ref(''), replies = reactive({})
const headers = () => ({ Authorization: `Bearer ${token.value}` })
const errorText = e => { const detail = e.response?.data?.detail; return typeof detail === 'string' ? detail : e.message || '请求失败' }
function choose(type) { form.type = type; page.value = 'publish'; window.scrollTo({ top: 320, behavior: 'smooth' }) }
function logout() { token.value = ''; username.value = ''; localStorage.removeItem('cat_token'); localStorage.removeItem('cat_user'); notice.value = '已退出登录' }
async function authenticate() { busy.value = true; try { if (registerMode.value) await axios.post('/api/v2/auth/register', auth); const { data } = await axios.post('/api/v2/auth/login', auth); token.value = data.access_token; username.value = auth.username; localStorage.setItem('cat_token', token.value); localStorage.setItem('cat_user', username.value); auth.password = ''; authOpen.value = false; notice.value = '登录成功' } catch (e) { notice.value = errorText(e) } finally { busy.value = false } }
function selectFiles(e) { const next = Array.from(e.target.files || []); if (next.length > 5 || next.some(f => !['image/jpeg', 'image/png'].includes(f.type) || f.size > 5 * 1024 * 1024)) { notice.value = '最多 5 张 JPG/PNG，每张不超过 5MB'; e.target.value = ''; return } previews.value.forEach(URL.revokeObjectURL); files.value = next; previews.value = next.map(URL.createObjectURL) }
function removeFile(i) { URL.revokeObjectURL(previews.value[i]); files.value.splice(i, 1); previews.value.splice(i, 1) }
onUnmounted(() => previews.value.forEach(URL.revokeObjectURL))
function useLocation() { if (!navigator.geolocation) { notice.value = '浏览器不支持定位'; return } navigator.geolocation.getCurrentPosition(p => { form.event_lat = p.coords.latitude; form.event_lng = p.coords.longitude; notice.value = '已填入当前位置，请确认这里就是事发地点' }, () => { notice.value = '定位失败，可只填城市和区县' }, { timeout: 10000 }) }
async function publish() { if (!token.value) { authOpen.value = true; notice.value = '请先登录'; return } if (!files.value.length) { notice.value = '请至少上传一张照片'; return } busy.value = true; matchesShown.value = false; try { const images = []; for (const file of files.value) { const body = new FormData(); body.append('image', file); const { data } = await axios.post('/api/v2/images', body, { headers: headers() }); images.push(data.image_url) } const payload = { species: 'cat', type: form.type, images, desc: { ...form.desc }, event_city: form.event_city, event_district: form.event_district, event_time: form.event_time.replace('T', ' '), event_lat: form.event_lat, event_lng: form.event_lng, contact: '' }; const created = await axios.post(`/api/v2/reports/${form.type}`, payload, { headers: headers() }); activeReport.value = { type: form.type, id: created.data.id }; const result = await axios.get(`/api/v2/reports/${form.type}/${created.data.id}/matches`, { headers: headers() }); matches.value = result.data.results || []; searchScope.value = result.data.scope || 'same_city'; matchTargetType.value = form.type === 'lost' ? 'sighting' : 'lost'; matchesShown.value = true; notice.value = '已发布。请进一步核实疑似匹配。' } catch (e) { notice.value = errorText(e) } finally { busy.value = false } }
async function navigate(target) { page.value = target; if (target === 'browse') await loadBrowse(); if (target === 'mine') await loadMine() }
async function loadBrowse() { try { const { data } = await axios.get('/api/v2/reports', { params: { type: browseType.value, city: browseCity.value || undefined } }); browseItems.value = data.items } catch (e) { notice.value = errorText(e) } }
async function loadMine() { if (!token.value) return; try { const [reports, requests] = await Promise.all([axios.get('/api/v2/me/reports', { headers: headers() }), axios.get('/api/v2/me/contact-requests', { headers: headers() })]); myItems.value = reports.data.items; contactItems.value = requests.data.items } catch (e) { notice.value = errorText(e) } }
async function viewMatches(item) { try { const { data } = await axios.get(`/api/v2/reports/${item.type}/${item.id}/matches`, { headers: headers() }); activeReport.value = { type: item.type, id: item.id }; matches.value = data.results || []; searchScope.value = data.scope || 'same_city'; matchTargetType.value = item.type === 'lost' ? 'sighting' : 'lost'; matchesShown.value = true; page.value = 'publish'; window.scrollTo({ top: 650, behavior: 'smooth' }) } catch (e) { notice.value = errorText(e) } }
async function expandMatches() { if (!activeReport.value) return; try { const { type, id } = activeReport.value; const { data } = await axios.get(`/api/v2/reports/${type}/${id}/matches`, { params: { expand: true }, headers: headers() }); matches.value = data.results || []; searchScope.value = data.scope; notice.value = '已扩大到全部城市' } catch (e) { notice.value = errorText(e) } }
async function closeReport(item) { try { await axios.patch(`/api/v2/reports/${item.type}/${item.id}/status`, { status: 'resolved' }, { headers: headers() }); item.status = 'resolved'; notice.value = '已标记为解决' } catch (e) { notice.value = errorText(e) } }
function contact(item, type) { if (!token.value) { authOpen.value = true; notice.value = '请先登录'; return } contactTarget.value = item; contactType.value = type; contactMessage.value = '' }
async function sendContact() { busy.value = true; try { await axios.post('/api/v2/contact-requests', { target_type: contactType.value, target_id: contactTarget.value.id, message: contactMessage.value }, { headers: headers() }); contactTarget.value = null; notice.value = '联系请求已发送' } catch (e) { notice.value = errorText(e) } finally { busy.value = false } }
async function reply(item) { if (!replies[item.id]?.trim()) return; try { await axios.post(`/api/v2/contact-requests/${item.id}/reply`, { reply: replies[item.id] }, { headers: headers() }); item.reply = replies[item.id]; item.state = 'replied'; notice.value = '已回复' } catch (e) { notice.value = errorText(e) } }
</script>

<style scoped>
* { box-sizing: border-box; } .shell { min-height: 100vh; background: #f7f8f3; color: #20382b; font-family: Inter, 'Microsoft YaHei', sans-serif; } button, input, select, textarea { font: inherit; } button { cursor: pointer; }
.topbar { max-width: 1160px; margin: auto; min-height: 74px; padding: 12px 22px; display: flex; align-items: center; justify-content: space-between; gap: 20px; } .brand { font-size: 21px; white-space: nowrap; } nav { display: flex; gap: 18px; } nav button, .link { border: 0; background: transparent; color: #5b6d61; padding: 7px; } nav button.active, nav button:hover, .link:hover { color: #237846; } main { max-width: 1160px; margin: auto; padding: 0 22px 80px; }
.hero { border-radius: 26px; padding: 58px 60px; background: linear-gradient(115deg,#e2f1dc,#f6eedc); } .eyebrow, .heading span { color: #318454; font-size: 12px; font-weight: 800; letter-spacing: .06em; } h1 { font-size: clamp(30px,4vw,49px); margin: 12px 0 18px; } h2 { font-size: 27px; margin: 7px 0; } h3 { margin: 8px 0; } .hero > p:not(.eyebrow) { max-width: 630px; color: #63756a; line-height: 1.7; } .actions { display: flex; gap: 12px; margin-top: 24px; flex-wrap: wrap; }
.primary,.secondary { border: 1px solid #2b8050; border-radius: 10px; padding: 12px 19px; font-weight: 700; } .primary { color: white; background: #287d4b; } .primary:hover { background: #1e603b; } .secondary { color: #287d4b; background: white; } .secondary:hover { background: #edf6ef; } .small { padding: 9px 13px; font-size: 13px; } .notice { padding: 12px 16px; border-radius: 10px; margin-top: 20px; background: #e8f5e9; color: #246c3f; }
.content { padding-top: 50px; } .heading { margin-bottom: 22px; } .heading p { color: #79877d; margin: 7px 0; } .switch { display: inline-flex; padding: 5px; border-radius: 12px; background: #e8ede6; margin-bottom: 20px; } .switch button { border: 0; border-radius: 9px; padding: 10px 22px; background: transparent; color: #53745e; } .switch button.selected { background: white; color: #267a47; box-shadow: 0 2px 9px #2c4b2e14; }
.panel,.dialog { background: white; border: 1px solid #e3e9e0; box-shadow: 0 12px 30px #233c290a; border-radius: 20px; padding: 28px; } .grid { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 20px; } label { display: flex; flex-direction: column; gap: 8px; font-size: 14px; font-weight: 700; } input,select,textarea { border: 1px solid #dbe4db; border-radius: 9px; background: white; color: #20382b; padding: 11px 12px; width: 100%; outline: none; } input:focus,select:focus,textarea:focus { border-color: #3e9b61; box-shadow: 0 0 0 3px #3e9b6125; } .location { display: flex; align-items: center; gap: 14px; background: #f7f9f4; border-radius: 12px; padding: 14px; margin: 22px 0; } .location > div { flex: 1; } .location p,.tip { font-size: 12px; color: #839086; margin: 5px 0; } .location span { font-size: 12px; color: #267a47; } .upload { border: 2px dashed #cbdccc; border-radius: 12px; padding: 18px; cursor: pointer; } .upload small { color: #839086; font-weight: 400; } .upload input { border: 0; padding-left: 0; } .previews { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 12px; } .previews > div { width: 110px; height: 110px; position: relative; } .previews img { width: 100%; height: 100%; border-radius: 9px; object-fit: cover; } .previews button { position: absolute; top: 3px; right: 3px; border: 0; border-radius: 50%; background: #263b2e; color: white; } .tip { margin: 18px 0; } .submit { width: 100%; } .submit:disabled { opacity: .6; cursor: wait; }
.results,.inbox { margin-top: 48px; } .result-grid { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 16px; } .result { display: flex; gap: 15px; border: 1px solid #e3e9e0; border-radius: 15px; background: white; padding: 13px; } .result > img { width: 142px; height: 155px; border-radius: 9px; object-fit: cover; } .result p,.result small { color: #718075; font-size: 13px; margin: 7px 0; } .empty { background: white; border: 1px solid #e3e9e0; border-radius: 15px; padding: 35px; text-align: center; color: #7d8b80; } .filters { display: flex; gap: 10px; margin-bottom: 20px; max-width: 590px; } .filters select { width: 155px; }
.my-list { display: grid; gap: 12px; } .my-item,.message { border: 1px solid #e3e9e0; background: white; border-radius: 13px; padding: 12px; } .my-item { display: flex; align-items: center; gap: 16px; } .my-item img { width: 90px; height: 90px; object-fit: cover; border-radius: 8px; } .my-item p { color: #7a897d; margin: 7px 0; } .my-actions { margin-left: auto; display: grid; gap: 6px; } .message { margin: 10px 0; } .message small { color: #7a897d; } .message > div { display: flex; gap: 8px; margin-top: 12px; }
.overlay { position: fixed; inset: 0; background: #112919a6; z-index: 10; display: grid; place-items: center; padding: 20px; } .dialog { position: relative; width: min(440px,100%); display: grid; gap: 15px; } .dialog h2 { margin: 0; } .dialog p { color: #718075; margin: 0; } .close { position: absolute; right: 14px; top: 10px; border: 0; background: none; font-size: 28px; }
@media(max-width:750px){ .topbar { flex-wrap: wrap; padding: 16px; } nav { order: 3; width: 100%; justify-content: space-between; gap: 3px; } nav button { font-size: 13px; } main { padding: 0 16px 60px; } .hero { padding: 34px 25px; } .grid,.result-grid { grid-template-columns: 1fr; } .location { flex-wrap: wrap; } .result > img { width: 110px; height: 130px; } .my-item { flex-wrap: wrap; } .my-actions { margin-left: 0; display: flex; width: 100%; } }
</style>
